{
  "items": [
    {
      "name": "Finsupp.weight_apply",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_2} {R : Type u_3} [inst : Semiring R] (w : σ → M) [inst_1 : AddCommMonoid M]\n  [inst_2 : Module R M] (f : σ →₀ R), (Finsupp.weight w) f = f.sum fun i c => c • w i"
    },
    {
      "name": "Finsupp.weight_single",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_2} {R : Type u_3} [inst : Semiring R] (w : σ → M) [inst_1 : AddCommMonoid M]\n  [inst_2 : Module R M] (s : σ) (r : R), (Finsupp.weight w) (Finsupp.single s r) = r • w s"
    },
    {
      "name": "Finsupp.weight",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {M : Type u_2} →\n    {R : Type u_3} → [inst : Semiring R] → (σ → M) → [inst_1 : AddCommMonoid M] → [Module R M] → (σ →₀ R) →+ M"
    },
    {
      "name": "Finsupp.sum_toMultiset",
      "module_name": "Mathlib.Data.Finsupp.Multiset",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : AddCommMonoid α] (f : α →₀ ℕ), (Finsupp.toMultiset f).sum = f.sum fun a n => n • a"
    },
    {
      "name": "finsum_eq_sum",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} [inst : AddCommMonoid M] (f : α → M) (hf : (Function.support f).Finite),\n  ∑ᶠ (i : α), f i = ∑ i ∈ hf.toFinset, f i"
    }
  ]
}
